// Decode JWT (mismo patrón que api_me - en producción extraer a util_jwt_decode)
const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');

  // Extract query params + parse cursor
  const q     = $input.first().json.query || {};
  const limit = Math.min(parseInt(q.limit || '25'), 100);
  let cursorAfter = null;
  if (q.cursor) {
    try { cursorAfter = JSON.parse(Buffer.from(q.cursor, 'base64url').toString('utf8')); } catch {}
  }

  return [{ json: {
    user_id:   payload.sub,
    tenant_id: payload.tenant_id || null,
    role:      payload.role      || 'architect',
    request_id: 'req_' + Math.random().toString(36).slice(2, 10),
    filters: {
      phase:    q.phase || null,
      phase_in: q.phase_in ? q.phase_in.split(',') : null,
      q:        q.q || null,
      status:   q.status || 'active',
      sort:     q.sort || 'updated_desc',
      limit,
      cursor_after: cursorAfter
    }
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const items = $input.all().map(i => i.json);
const sess  = $('Decode JWT + Params').first().json;
const limit = sess.filters.limit;

// Si trajimos limit+1, hay más páginas
const hasMore = items.length > limit;
const page    = hasMore ? items.slice(0, limit) : items;

let cursorNext = null;
if (hasMore && page.length > 0) {
  const last = page[page.length - 1];
  cursorNext = Buffer.from(JSON.stringify({
    id: last.id,
    ts: last.updated_at
  })).toString('base64url');
}

return [{ json: {
  data: page.map(p => ({
    id:                       p.id,
    name:                     p.name,
    client_name:              p.client_name,
    current_phase:            p.current_phase,
    status:                   p.status,
    budget_target:            p.budget_target ? parseFloat(p.budget_target) : null,
    location_city:            p.location_city,
    created_at:               p.created_at,
    updated_at:               p.updated_at,
    alerts_count:             parseInt(p.alerts_count) || 0,
    pending_approvals_count:  parseInt(p.pending_approvals_count) || 0
  })),
  meta: {
    request_id: sess.request_id,
    timestamp:  new Date().toISOString(),
    pagination: {
      cursor_next:     cursorNext,
      cursor_prev:     null,
      has_more:        hasMore,
      total_estimated: page.length + (hasMore ? 1 : 0)
    }
  }
}}];
